    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bars = [r for r, row in enumerate(grid) if row and all(v == 2 for v in row)]
    if not bars:
        return out
    bar = bars[0]

    # The colored marks on opposite sides of the separator select shared columns.
    upper_rows = [r for r in range(bar) if any(v != 0 for v in grid[r])]
    lower_rows = [r for r in range(bar + 1, h) if any(v != 0 for v in grid[r])]
    if not upper_rows or not lower_rows:
        return out
    upper = grid[upper_rows[0]]
    lower = grid[lower_rows[-1]]
    for c in range(w):
        if upper[c] != 0 and upper[c] == lower[c]:
            for r in range(upper_rows[0] + 1, bar):
                if out[r][c] == 0:
                    out[r][c] = 4
    return out
